# A hand-made tree over 3 columns: external nodes at depths 1 to 4,
# holding 1 to 6 rows, so several of them are truncated.
def node(depth):
    if depth == 4 or (depth >= 1 and rng.random() < 0.3):
        return {"size": int(rng.integers(1, 7))}
    return {"attr": int(rng.integers(3)), "split": float(rng.normal(0.0, 0.7)),
            "left": node(depth + 1), "right": node(depth + 1)}
tree = node(0)
X = rng.normal(size=(50, 3))
inputs = (X, tree)
